function Icon({ name, size = 19 }: { name: string; size?: number }) { return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.65" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{paths[name] || paths.grid}</svg>; }
async function api(path: string, method = 'GET', body?: unknown, key?: string) {
  const response = await fetch('/api' + path, { method, credentials: 'same-origin', headers: { ...(body !== undefined ? { 'Content-Type': 'application/json' } : {}), ...(key ? { 'Idempotency-Key': key } : {}) }, ...(body !== undefined ? { body: JSON.stringify(body) } : {}) });
  const data = await response.json().catch(() => ({ error: 'The server returned an unreadable response.' }));
  if (!response.ok) throw Object.assign(new Error(typeof data.error === 'string' ? data.error : data.error?.message || 'The request could not be completed.'), { status: response.status, code: data.error?.code, operation: data.operation, run: data.run });
  return data;
}
const money = (n: unknown, currency = 'AED') => new Intl.NumberFormat('en-AE', { style: 'currency', currency, maximumFractionDigits: 0 }).format(Number(n) || 0);
const compact = (n: unknown) => new Intl.NumberFormat('en', { notation: 'compact', maximumFractionDigits: 1 }).format(Number(n) || 0);
const title = (s: string) => s ? s.charAt(0).toUpperCase() + s.slice(1).replaceAll('_', ' ') : '';
const date = (value: string) => value ? new Date(value).toLocaleDateString('en-GB', { day: 'numeric', month: 'short' }) : 'Not set';
const initial = (value: string) => value?.split(' ').map(s => s[0]).slice(0, 2).join('').toUpperCase() || '98';
function conversationKey(row: Row) { return JSON.stringify([row.accountId || null, row.externalConversationId || row.id || row._id]); }
function mergeMessages(messages: Row[], updates: Row[]) { const merged = new Map([...messages, ...updates].map(row => [String(row.id || row._id || row.platformMessageId || (row.createdAt || '') + ':' + (row.content || row.text || '')), row])); return [...merged.values()].sort((a, b) => (Date.parse(a.createdAt || a.sentAt || '') || 0) - (Date.parse(b.createdAt || b.sentAt || '') || 0)); }
function Badge({ value }: { value: string }) { return <span className={'badge ' + value?.toLowerCase().replaceAll(' ', '-')}><i/>{title(value || 'draft')}</span>; }
function Platform({ name }: { name: string }) { return <span className={'platform ' + name} title={title(name)}>{({ instagram: '◎', facebook: 'f', linkedin: 'in', tiktok: '♪', twitter: '𝕏', youtube: '▶', pinterest: 'p', threads: '@', bluesky: 'b' } as Record<string, string>)[name] || name?.slice(0, 1).toUpperCase()}</span>; }
function Empty({ icon = 'folder', title: heading, children, action }: { icon?: string; title: string; children: React.ReactNode; action?: React.ReactNode }) { return <div className="empty"><span className="empty-icon"><Icon name={icon} size={25}/></span><h3>{heading}</h3><p>{children}</p>{action}</div>; }
function AssetPreview({ item }: { item: Row }) {
  const [failed, setFailed] = useState(false);
  let preview = '';
  try { const target = new URL(item.thumbnailUrl || (item.kind === 'image' ? item.url : '')); if (target.protocol === 'https:' && !['drive.google.com', 'docs.google.com'].includes(target.hostname) && !target.username && !target.password && !/^(localhost|127\.|10\.|192\.168\.|169\.254\.|0\.|\[)/.test(target.hostname) && !/\.(local|internal)$/.test(target.hostname)) preview = target.href; } catch {}
  return preview && !failed ? <img className="real-asset-preview" src={preview} alt={item.description || item.name} loading="lazy" referrerPolicy="no-referrer" onError={() => setFailed(true)}/> : <div className={'asset-placeholder ' + item.kind}><Icon name={item.kind === 'document' ? 'folder' : 'image'} size={42}/><span>{title(item.kind)}</span></div>;
}
function Creative({ item, small = false }: { item: Row; small?: boolean }) { return <div className={'creative ' + (small ? 'small ' : '') + (item.kind === 'video' ? 'creative-video' : item.kind === 'document' ? 'creative-doc' : '')}><div className="creative-orbit"/><span className="creative-label">ten98 / studio</span><strong>{item.kind === 'document' ? 'The brand\nplaybook.' : item.kind === 'video' ? 'Make your\nnext move.' : 'Made to\nstand out.'}</strong><span className="creative-foot">{item.kind === 'video' ? '▶  BRAND FILM' : item.kind === 'document' ? 'BRAND GUIDELINES · 2026' : 'A NEW PERSPECTIVE'}</span></div>; }

