  useEffect(() => { setQuery(''); setTab('all'); setMobile(false); setError(''); }, [page]);
  useEffect(() => { if (!state?.projectId) return; setRemote({}); setOohInventory([]); setCalendarEvents([]); setModal(null); activeChat.current = ''; setSelectedChat(''); setMessages([]); const id = state.projectId; api(endpoint('integrations/status')).then(status => { if (activeProject.current === id) setRemote((r: any) => ({ ...r, status })); }).catch(() => {}); }, [state?.projectId]);
