      {modal.type === 'post' && <><Field label="Post content" name="content" defaultValue={modal.item?.content} multiline required maxLength={10000} placeholder="What’s your story?"/><label className="field-label">Publish to</label><div className="platform-options">{platforms.map(p => <label key={p}><input type="checkbox" name="platforms" value={p} defaultChecked={modal.item?.platforms?.includes(p) || false}/><Platform name={p}/>{title(p)}</label>)}</div>{remote.accounts?.accounts?.length > 0 && <><label className="field-label">Connected accounts</label><div className="account-options">{remote.accounts.accounts.filter((a: Row) => !a.platform?.endsWith('ads')).map((a: Row) => <label key={a.id || a._id}><input type="checkbox" name="accounts" value={a.id || a._id} defaultChecked={modal.item?.accounts?.includes(a.id || a._id)}/>{a.displayName || a.username || a.name} ({a.platform})</label>)}</div></>}<Select label="Creative asset" name="assetId" value={modal.item?.assetId || ''} options={[["", 'No asset'], ...state.assets.map(a => [a.id, a.name])]}/><Select label="Campaign" name="campaignId" value={modal.item?.campaignId || ''} options={[["", 'No campaign'], ...state.campaigns.map(c => [c.id, c.name])]}/><Field label="Plan for (optional)" name="scheduledAt" type="datetime-local" defaultValue={modal.day || (modal.item?.scheduledAt ? new Date(new Date(modal.item.scheduledAt).getTime() - new Date(modal.item.scheduledAt).getTimezoneOffset() * 60000).toISOString().slice(0, 16) : '')}/><p className="field-help">Save your draft here, then choose Publish or Schedule to submit it to Zernio. Planned posts are not sent automatically.</p>{modal.item?.externalId && <div className="alert">This post was submitted to Zernio. Create a new draft for content changes.</div>}</>}
